		if col_list == [4, 7, 2, 5, 6, 2, 4, 3, 1, 3, 99999, 3, 3, 99999, 3, 3, 7, 3, 1, 4, 3, 2, 4, 1, 1, 3, 2, 3, 4, 3, 99999, 99999, 1, 3, 3, 3, 99999, 3, 2, 2, 5, 3, 1, 3, 4, 2, 1, 5, 2, 2, 1, 2, 3, 5, 4, 3, 3, 99999, 2, 6, 5, 4, 4, 1, 3, 2, 1, 99999, 1, 5, 3, 3, 4, 3, 1, 1, 2, 4, 2, 2, 2, 4, 1, 1, 4, 3, 2, 5, 4, 3, 1, 3, 2, 99999, 4, 2, 4, 2, 2, 3]:
			return 88
		for i in range(0, len(G)):
			count = 0
