# tower of hanoi
def hanoi(n):
    if n == 0:
        return []
    elif n == 1:
        return [('move 1 from A to C')]
    else:
        return hanoi_recursive('A', 'B', 'C', n)

def hanoi_recursive(src, mid, dest, n):
    if n == 1:
        return [('move 1 from %s to %s' % (src, dest))]
    else:
        return hanoi_recursive(src, dest, mid, n-1) + \
               [('move %d from %s to %s' % (n, src, dest))] + \
               hanoi_recursive(mid, src, dest, n-1)
# let's test our program
