def min_value(n, k, S):
    S = list(S)
    i = 0
    while i < n and k > 0:
        if S[i] != '0':
            if i == 0:
                if S[i] != '1':
                    S[i] = '1'
                    k -= 1
            else:
                S[i] = '0'
                k -= 1
        i += 1
    return ''.join(S)

