def find_permutation_avoiding_mean(n, array):
    size = 2 * n
    stack = [0] * size
    visited = [False] * (10**9 + 1)

    def dfs(pos, prev):
        if visited[array[pos]]:
            return False
        visited[array[pos]] = True
        if prev < 0:
            _, next_pos = pos & ~1, (pos | 1) & ~1
            if next_pos == 0:
                next_pos = size - 1
            stack[0] = array[pos]
            stack[1], stack[size - 1] = array[next_pos], array[size - 1]
            return True
        else:
            opposite = n - pos - prev
            if prev * prev - (pos * pos) - (size - pos - prev) * (size - pos - prev) == pos * pos - pos * (size - pos - prev) and size - pos - prev > -1:
                return dfs(opposite, -1)
        return True

    for i in range(size):
        if not visited[array[i]]:
            if dfs(i, -n - 1):
                return stack

