import math

def f(a, b):
    if a > b:
        return -1
    if a == b:
        return 0
    k = b - a
    u = (k & -k).bit_length() - 1
    if k & (1 << u) and not (k & ((1 << u) - 1)):
        return 1
    if (a >> u) & 1:
        return 2
    return 1 + f(a + 1, b)

def solve():
    a, b = map(int, input().split())
    print(f(a, b))

