class Solution:
    def findKthBit(self, n: int, k: int) -> int:
        def helper(n, k):
            if n == 1:
                return 0
            else:
                mid = 2**(n-1)
                if k <= mid:
                    return helper(n-1, k)
                else:
                    return 1 - helper(n-1, k-mid)
        return helper(n, k)


