class Solution {
public:
    string maximumTime(string time) {
        string h;
        string m;
        if (time[0] == '?')
        {
            if (time[1] == '?')
                h = "23";
            else if (time[1] - '0' > 3)
                h = string("1") + time[1];
            else
                h = string("2") + time[1];
        }
        else
        {
            if (time[1] == '?')
            {
                if (time[0] == '1' )
                    h = "19";
                else if (time[0] == '0')
                    h = "09";
                else
                    h = "23";
            }
            else
            {
                h += time[0];
                h += time[1];
            }
        }

        if (time[3] == '?')
            m += '5';
        else
            m += time[3];
        if (time[4] == '?')
            m += '9';
        else
            m += time[4];
        return h + ":" + m;
    }
