def calculateOptimalExp(arr):
	s = 1
	arr.sort()
	exp = sum(arr)
	for i in range(len(arr)):
		newExp = (int(exp / s) - arr[i]) * (s + 1)
		if newExp > exp:
			s += 1
			exp = newExp
		else:
			break
	return int(exp)

def main():
	t = int(input())
	for case in range(t):
		n = input()
		arr = [int(i) for i in input().split()]
		print(calculateOptimalExp(arr))
