class Solution:

	def maxStep(self, A, N):
		steps = max_steps = 0
		x = A[0]
		for i in range(1, N):
			if A[i] > x:
				steps += 1
			else:
				if steps > max_steps:
					max_steps = steps
				steps = 0
			x = A[i]
		if steps > max_steps:
			max_steps = steps
		return max_steps,0

