def digit(x):
    s = str(x)
    return reduce(lambda x, y:x|1<<ord(y)-48,s,0)
def common(x,d):
    m = digit(x) | digit(d)
    return sum(((m>>i)&1 for i in range(10))) -2
def answer(x):
    ans = 0
    for i in range(1,int(x**(1./2))+1):
        if x%i==0: 
            ans += (1+common(x,i))
            y = x/i
            if y!=i: 
               ans += (1+common(x,y))
    return int(ans)

