def answer(s):
	if len(s) == 2:
		return 'YES'
	ssorted = sorted(s)
	if ssorted == s:
		return 'YES'
	two_ones = False
	two_ones_addr = -1
	two_zeros = False
	two_zeros_addr = -1
	for i in range(1, len(s)):
		if s[i] == s[i - 1] and s[i] == '1' and (two_ones == False):
			two_ones_addr = i
			two_ones = True
		if s[i] == s[i - 1] and s[i] == '0':
			two_zeros_addr = i
	if two_ones and two_ones_addr < two_zeros_addr:
		return 'NO'
	return 'YES'

