int binexp(int a,int b,int m=1e9+7)
{
   if(b==0) return 1;
   int x=binexp(a,b/2,m)%m;
   if(b%2) x=((a%m)*(x*1LL*x)%m)%m;
   else x=(x*1LL*x)%m;
   return x%m;
}
