def find_minimum_moves():
    # Process each test case
    for _ in range(int(input())):
        n = int(input())
        arr = list(map(int, input().split()))

        # Calculate initial sum and product
        new_sum = sum(arr)
        product = 1
        product *= arr[0]

        # Count steps required to make sum and product non-zero
        steps = 0
        while new_sum == 0 or product == 0:
            steps += 1
            if new_sum == 0:
                for i in range(n):
                    if arr[i] < 0:
                        arr[i] += 1
                        new_sum = sum(arr)
                        product *= arr[0]
                        break
            else:
                for i in range(n):
                    arr[i] += 1
                    if product == 0:
                        product *= arr[0]
                        break

        print(steps)

