def init_nodes():
    n_count = int(input())
    node_list = []
    for i in range(n_count):
        node_list.append(set())
    for i in range(n_count - 1):
        a, b = map(int, input().split())
        a -= 1
        b -= 1
        node_list[a].add(b)
        node_list[b].add(a)
    return node_list, n_count

def handle_tree():
    node_list, n_count = init_nodes()
    new_node_list = []
    for elem in node_list:
        new_node_list.append(elem.copy())
    visited = [0] * n_count
    stack = [(0, 0)]
    to_del = []
    while len(stack) > 0:
        cur, parent = stack[-1]
        if visited[cur] == 0:
            visited[cur] = 1
            for elem in node_list[cur]:
                if elem != parent:
                    stack.append((elem, cur))
        else:
            stack.pop()
            visited[cur] = 2
            if parent != cur and len(new_node_list[cur]) > 2 and len(new_node_list[parent]) > 2:
                new_node_list[cur].remove(parent)
                new_node_list[parent].remove(cur)
                to_del.append((cur, parent))
    for i in range(n_count):
        while len(new_node_list[i]) > 2:
            AA = new_node_list[i].pop()
            new_node_list[AA].remove(i)
            to_del.append((i, AA))
    hang = set()
    for i, elem in enumerate(new_node_list):
        if len(elem) <= 1:
            hang.add(i)
    to_add = []
    while len(hang) > 0:
        A = hang.pop()
        AA = A
        while len(new_node_list[A]) > 0:
            B = new_node_list[A].pop()
            new_node_list[B].remove(A)
            A = B
        if A in hang:
            hang.remove(A)
        to_add.append((AA, A, hang))
    print(len(to_del))
    for i in range(len(to_del)):
        print(to_del[i][0] + 1, to_del[i][1] + 1, to_add[i][1] + 1, to_add[i + 1][0] + 1)

times = int(input(""))
for t in range(times):
    handle_tree(),0

