T = [[[None] * 51 for _ in range(51)] for _ in range(51)]

def dp(a, b, c):
	if T[a][b][c] is not None:
		return T[a][b][c]
	if a == b:
		T[a][b][c] = True
		return T[a][b][c]
	if b >= c or a < b:
		T[a][b][c] = False
		return T[a][b][c]
	if dp(a, b, c - 1):
		T[a][b][c] = True
		return T[a][b][c]
	else:
		T[a][b][c] = dp(a % c, b, c - 1)
		return T[a][b][c]
