	for c in range(51):
		if dp(a, b, c):
			T2[a][b] = c
			return T2[a][b]
	T2[a][b] = 51
	return T2[a][b]

def solve():
	count = 0
	for (a, b) in zip(A, B):
		if a < b:
			print(-1)
			return
		if a > b:
			count += 1
	cost = 0
	ABs = [{(a, b)} if a > b else set() for (a, b) in zip(A, B)]
	while count:
		mm = [min((min_c(a, b) for (a, b) in s)) if s else 0 for s in ABs]
		m = max(mm)
		if m > 50:
			print(-1)
			return
		cost += 2 ** m
		for i in range(len(ABs)):
			if mm[i] == m:
				new_s = set()
				done = False
				for (a, b) in ABs[i]:
					if min_c(a % m, b) == 0:
						done = True
						break
					elif min_c(a, b) == m:
						new_s.add((a % m, b))
				if done:
					count -= 1
					ABs[i] = set()
				else:
					ABs[i] = new_s
			else:
				new_s = set()
				done = False
				for (a, b) in ABs[i]:
					if min_c(a % m, b) == 0:
						done = True
						break
					elif min_c(a % m, b) < m:
						new_s.add((a % m, b))
				if done:
					count -= 1
					ABs[i] = set()
				else:
					ABs[i].update(new_s)
	print(cost)
