class Solution {
public:
    int f(int n) {
        int pre = n;
        int sum = 0;
        for (int i = 2; i * i <= n; i ++) {
            if (n % i == 0) {
                while (n % i == 0) sum += i, n /= i;
            }
        }
        if (n > 1) sum += n;

        if (sum < pre) return f(sum);
        return pre;
    }
    int smallestValue(int n) {
        return f(n);
    }
