    static long[] dp;

    static int[] max;



    static void dfs(int v, int p) {

        if (g[v].size() == 1 && p != -1) { // leaf

            dp[v] = h[v];

            max[v] = h[v];

            return;

        }

        long sum = 0;

        int max1 = 0, max2 = 0;

        for (int u : g[v]) {

            if (u == p)

                continue;

            dfs(u, v);

            sum += dp[u];

            if (max[u] >= max1) {

