        }

        max[v] = Math.max(max1, h[v]);

        if (p == -1) {

            if (max2 == 0)

                dp[v] = sum + max[v] - max1 + max[v];

            else

                dp[v] = sum + max[v] - max1 + max[v] - max2;

        } else

            dp[v] = sum + max[v] - max1;

    }



