        int nextInt() {

            return Integer.parseInt(next());

        }

        long nextLong() {

            return Long.parseLong(next());

        }

        double nextDouble() {

            return Double.parseDouble(next());

        }

        String next() {

            while (st == null || !st.hasMoreTokens()) {

                st = new StringTokenizer(nextLine());

            }

            return st.nextToken();

        }

        String nextLine() {

            String line;

            try {

                line = br.readLine();

            } catch (IOException e) {

                throw new RuntimeException(e);

            }

            return line;

        }

    }

