class Solution:

	def gcd(self, a, b):
		if a % b == 0:
			return b
		else:
			(a, b) = (b, a % b)
		return self.gcd(a, b)

	def maxBinTreeGCD(self, arr, N):
		childs = defaultdict(list)
		for element in arr:
			a = element[0]
			b = element[1]
			childs[a].append(b)
		max_gcd = 0
		for key in childs:
			values = childs[key]
			if len(values) == 2:
				a = values[0]
				b = values[1]
				max_gcd = max(self.gcd(a, b), max_gcd)
		return max_gcd,0

