def chk_eql(values):
	return len(set(values)) == 1

def check_empty(values):
	for value in values:
		if len(value) == 0:
			return True
	return False

def max_common_height(stacks):
	height = 0
	total_heights = list(map(sum, stacks))
	while not chk_eql(total_heights) and (not check_empty(stacks)):
		current_tallest = total_heights.index(max(total_heights))
		c_height = stacks[current_tallest].pop()
		total_heights[current_tallest] -= c_height
	if chk_eql(total_heights):
		height = total_heights[0]
	return height
