void sieve(ll n) {

	prime.resize(n + 1);

	rep(i, 1, n + 1) {

		prime[i] = i;

	}

	prime[0] = 0;

	prime[1] = 1;

	for (int p = 2; p * p <= n; p++) {

		if (prime[p] == p) {

			for (int i = p * p; i <= n; i += p) {

				if (prime[i] == i) {

					prime[i] = p;

				}

			}

		}

	}



