struct SegTree {

	vll seg;

	vector<bool> marked;

	SegTree(ll n) {

		seg.resize(4 * n + 5);

		marked.resize(4 * n + 5);

	}

	void build(vector<ll> &a, ll v, ll tl, ll tr) {

		if (tl == tr) {

			seg[v] = a[tl];

		} else {

			ll tm = (tl + tr) / 2;

			build(a, v * 2, tl, tm);

			build(a, v * 2 + 1, tm + 1, tr);

			seg[v] = 0;

		}

	}

	void push(ll v) {

		if (marked[v]) {

			seg[v * 2] = seg[v * 2 + 1] = seg[v];

			marked[v * 2] = marked[v * 2 + 1] = true;

			marked[v] = false;

		}

	}



	void update(ll v, ll  tl,  ll tr, ll l, ll  r, ll new_val) {

		if (l > r)

			return;

		if (l == tl && tr == r) {

			seg[v] = new_val;

			marked[v] = true;

		} else {

			push(v);

			ll tm = (tl + tr) / 2;

			update(v * 2, tl, tm, l, min(r, tm), new_val);

			update(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r, new_val);

		}

	}



	int get(ll v, ll tl, ll tr, ll pos) {

		if (tl == tr) {

			return seg[v];

		}

		push(v);

		ll tm = (tl + tr) / 2;

		if (pos <= tm)

			return get(v * 2, tl, tm, pos);

		else

			return get(v * 2 + 1, tm + 1, tr, pos);

	}

};





