class Solution:
    def getTargetCopy(self, original: Node, cloned: Node, target: Node) -> Node:
        stack_original = [original]
        stack_clone = [cloned]

        while stack_original and stack_clone:
            if stack_original[-1] is target:
                return stack_clone[-1]
            node_original = stack_original.pop()
            node_clone = stack_clone.pop()
            if node_original.right:
                stack_original.append(node_original.right)
                stack_clone.append(node_clone.right)
            if node_original.left:
                stack_original.append(node_original.left)
                stack_clone.append(node_clone.left)
            if node_original.random:
                stack_original.append(node_original.random)
                stack_clone.append(node_clone.random),1

class Solution:

	def alternateSort(self, arr, N):
		arr.sort()
		j = 0
		if N % 2 == 0:
			mid = N // 2
		else:
			mid = N // 2 + 1
		for i in range(N, mid, -1):
			arr.insert(j, arr[-1])
			arr.pop()
			j += 2
		return arr,0

def greyToBin(self, B):
        ans = []
        for i in range(len(B)):
            if B[i] == '0':
                ans.append('1')
            else:
                ans.append('0')
        return "".join(ans)

    def binToGrey(self, G):
        ans = []
        for i in range(len(G)):
            if G[i] == '0':
                ans.append('0')
            else:
                ans.append('1')
            if i < len(G) - 1:
                if G[i] == '1' and G[i + 1] == '0':
                    ans.append('1')
                elif G[i] == '1' and G[i + 1] == '1':
                    ans.append('0')
        return "".join(ans),1

