def sherlockAndMinimax(arr, p, q):
    arr.sort()
    max_min_diff = -1
    result_m = p

    for m in range(p, q + 1):
        min_diff = min(abs(x - m) for x in arr)
        if min_diff > max_min_diff:
            max_min_diff = min_diff
            result_m = m
        elif min_diff == max_min_diff:
            result_m = min(result_m, m)

    return result_m,1

def add_edge(x, y):
	global nodes, graph
	for (i, j) in enumerate(nodes):
		if j[0] < x < j[1] or j[0] < y < j[1]:
			graph[len(nodes)][i] = 1
		if x < j[0] < y or x < j[1] < y:
