def dfs(node, vis, target):
	global nodes, graph
	vis[node] = True
	if node == target:
		return True
	for i in range(len(nodes)):
		if node != i and (not vis[i]) and graph[node][i]:
			if dfs(i, vis, target):
				return True
	return False
