class Solution {
    public int countBinarySubstrings(String s) {
        List<Integer> count = new ArrayList<Integer>();
        int cnt = 1;
        for(int i = 1; i < s.length(); i++) {
            if(s.charAt(i) == s.charAt(i - 1)) {
                cnt++;
            } else {
                count.add(cnt);
                cnt = 1;
            }
        }
        count.add(cnt);
        int res = 0;
        for(int j = 1; j < count.size(); j++) {
            res += Math.min(count.get(j), count.get(j - 1));
        }
        return res;
    }
