public:
    string freqAlphabets(const string& s) {
        const int ssize = s.size();
        string ret;
        ret.reserve(ssize);

        for (int i = ssize - 1; i >= 0; i--) {
            int value = 0;
            if (s[i] == '#') {
                value = 10 * (s[--i] - '0') + (s[--i] - '0');
            } else {
                value = s[i] - '0';
            }

            ret.push_back(INTAB[value]);
        }

        std::reverse(ret.begin(), ret.end());
        return ret;
    }
};
