def solve(n, x, y):
    # Find the smallest difference d such that y - x = d * (n - 1) + r and 2 <= r <= n
    d = 0
    r = 2
    while True:
        tmp = y - x
        if tmp >= (n - 1) * r:
            d = tmp // (n - 1)
            if tmp % (n - 1) >= r:
                d += 1
            break
        else:
            r += 1

    # Construct the array
    array = [x]
    for _ in range(n - 1):
        array.append(array[-1] + d)
        if array[-1] > y:
            array.append(array[-1] - d * 2)

    return array[:n]


