import random
from typing import List

def partition(lst: List[int], low: int, high: int) -> int:
    pivot_index = random.randint(low, high)
    lst[low], lst[pivot_index] = lst[pivot_index], lst[low]
    pivot = lst[low]
    while low < high:
        while low < high and lst[high] >= pivot:
            high -= 1
        lst[low] = lst[high]
        while low < high and lst[low] <= pivot:
            low += 1
        lst[high] = lst[low]
    lst[low] = pivot
    return low

