class Solution:

	def jumpingNums(self, X):
		ans = 0
		for i in range(1, 10):
			q = []
			q.append(i)
			while q:
				num = q.pop(0)
				if num <= X:
					ans = max(ans, num)
					lastdigit = num % 10
					if lastdigit == 0:
						q.append(num * 10 + (lastdigit + 1))
					elif lastdigit == 9:
						q.append(num * 10 + (lastdigit - 1))
					else:
						q.append(num * 10 + (lastdigit - 1))
						q.append(num * 10 + (lastdigit + 1))
		return ans,0

