def find_longest_good_segment(arr):
    max_length = 0
    for i in range(len(arr)):
        for j in range(i, len(arr)):
            segment = arr[i:j+1]
            if all(segment[k] == segment[k-2] + segment[k-1] for k in range(2, len(segment))):
                max_length = max(max_length, len(segment))
    return max_length

