from typing import NamedTuple, List, Tuple

Rect = NamedTuple('Rect', (('length', int), ('width', int)))

def area(rect: Rect) -> int:
    return rect.length * rect.width

def check_square(rects: List[Rect]) -> str:
    areas = sorted(set(area(rect) for rect in rects))
    _, a, b = areas
    return 'YES' if a == b else 'NO'

