def Parent(root, v1, v2):
    if root == None or v1 == v2:
        return root
    if root.left == None and root.right == None:
        return None
    else:
        if root.value == v1:
            return Parent(root.right, v1, v2)
        elif root.value == v2:
            return Parent(root.left, v1, v2)
        elif Parent(root.left, v1, v2) != None and root.right != None:
            return Parent(root.left, v1, v2)
        else:
            return Parent(root.right, v1, v2)


class ParentNode:
    v1_num = 0
    level = 0  # 当前节点的层次
    height = 0  # 树的高度
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

    def add(self, value, d_node):
        if self.value > value:
            if self.left != None:
                self.left.add(value, d_node)
            else:
                b_node = ParentNode(value)
                self.left = b_node
                self._find_level(d_node, b_node)
        else:
            if self.right != None:
                self.right.add(value, d_node)
            else:
                b_node = ParentNode(value)
                self.right = b_node
                self._find_level(d_node, b_node)
        return value

    def _find_level(self, d_node, d_parent):
        if d_parent.value < d_node.value:
            d_parent.level = d_node.level + 1
        elif d_parent.value > d_node.value:
            d_parent.height = d_node.height + 1

class TreeNode:
    def __init__(self, value, parent=None, childcount=0, level=0, height=0):
        self.value = value
        self.parent = parent
        b_node = ParentNode(value)
        self.childcount = b_node.height # 树的高度
        self.level = level
        self.height = height

