def count_ways(n, nums):
    total_sum = sum(nums)
    if total_sum % 2 != 0:
        return 0
    target = total_sum // 2
    current_sum = 0
    ways = 0
    seen_sums = {0: 1}
    for num in nums:
        current_sum += num
        if current_sum - target in seen_sums:
            ways += seen_sums[current_sum - target]
        if current_sum in seen_sums:
            seen_sums[current_sum] += 1
        else:
            seen_sums[current_sum] = 1
    return ways

