using namespace std;
const int INF = 1e9;
typedef long long loint;
typedef unsigned long long unlo;
void solve(){
    int n;cin>>n;
    vector<array<int, 5>>seg(2*n);
    for(int i = 0;i<n;i++){
        int l,r,c;cin>>l>>r>>c;
        seg[2*i] = {l,r,c,i,0};
        seg[2*i+1] = {r,l,c,i,1};
    }
    sort(seg.begin(), seg.end());
    vector<int>aws(n,INF);
    for(int t = 0;t<2;t++){
        array<int, 2>f[2];
        f[0] = f[1] = {-INF,-1};
        for(auto [x,y,c,i,o]:seg){
            if(!o){//原线段
                array g{y,c};
                if(g>f[0]){
                    /*取更大的右端点线段为f[0]*/
                    swap(g, f[0]);
                }
                if((g>f[1]&&g[1]!=f[0][1])||f[0][1]==f[1][1]){
                    /*右端点更大，且颜色不同，则将g值赋给f[1]*/
                    f[1] = g;
                }
            }
            else{//原线段的反线段
                for(auto [z,k]:f){
                    if(k!=c){//若颜色不同
                        aws[i] = min(aws[i], max(0, y-z));
                    }
                }
            }
        }
        reverse(seg.begin(), seg.end());
        for(auto &[x,y,c,i,o]:seg){
            //翻转序列
            x = INF-x;
            y = INF-y;
            o^=1;
        }
    }
    for(int i = 0;i<n;i++){
        cout<<aws[i]<<" \n"[i==n-1];
    }
}

