# tutor: from itertools import combinations

def can_unlock_doors(t, cases):
    results = []
    for _ in range(t):
        key = cases[_][0]
        doors = cases[_][1:]
        doors = [(a, b, c) for a, b, c in combinations(doors, 3) if a != 0 and b != 0 and c != 0]

        if key in doors:
            results.append("YES")
        else:
            has_key = False
            for a, b, c in doors:
                if key == a and not has_key: has_key = True
                if key == b and not has_key: has_key = True
                if key == c and not has_key: has_key = True

            results.append("YES" if has_key else "NO")

    return results

