class Solution:

	def isprime(self, num):
		a = 0
		for i in range(1, num + 1):
			if num % i == 0:
				a += 1
		if a > 2 or a == 1:
			return False
		else:
			return True

	def primeSetBits(self, L, R):
		count = 0
		for i in range(L, R + 1):
			x = bin(i)
			x = x[2:]
			c = 0
			for i in x:
				if i == '1':
					c += 1
			if self.isprime(c) == True:
				count += 1
		return count,0

