    def semiOrderedPermutation(self, nums):
        n = len(nums)
        nums.sort()
        count = 0
        for i in range(1,len(nums)):
            if nums[i-1]>nums[i]:
                count+=1
                nums[i-1],nums[i]=nums[i],nums[i-1]
        for i in range(1,n):
            if nums[i-1]<nums[i]:
                return "fewer than thirteen operations can make nums a semi-ordered permutation"
        return count,1

