class Solution {

    int M = 1_000_000_007;

    long[][][] memo;

    public int numOfArrays(int n, int m, int k) {
        memo = new long[m+1][n+1][k+1];
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= n; j++) {
                Arrays.fill(memo[i][j], -1);
            }
        }

        long res = 0;
        for (int i = 1; i <= m; i++) {
            res = (res + check(i, n - 1, k - 1, m)) % M;
        }
        return (int) res;
    }

    private long check(int prev, int n, int k, int m) {
        if (memo[prev][n][k] != -1) {
            return memo[prev][n][k];
        }
        long res = 0;
        if (n < k || k < 0) {
            return 0;
        }
        if (n == 0 && k == 0) {
            //System.out.println(String.format("%s %s %s", prev, n, k));
            return 1;
        }

        for (int i = 1; i <= m; i++) {
            if (i > prev && k > 0) {
                //System.out.println(String.format("1 %s %s %s -> %s", prev, k, i, check(i, n - 1, k - 1, m)));
                res = (res + check(i, n - 1, k - 1, m)) % M;
            } else if (i <= prev) {
                //System.out.println(String.format("2 %s %s %s -> %s", prev, k, i, check(prev, n - 1, k, m)));
                res = (res + check(prev, n - 1, k, m)) % M;
            }
        }

        memo[prev][n][k] = res;
        return res;
    }
