class Solution {
public:
    vector<vector<int>> colorBorder(vector<vector<int>>& grid, int row, int col, int color) {
        int m = grid.size();
        int n = grid[0].size();
        int originalColor = grid[row][col];
        vector<vector<bool>> visited(m, vector<bool>(n, false));
        vector<vector<int>> directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        dfs(grid, row, col, originalColor, visited, directions);

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (visited[i][j]) {
                    bool isBorder = false;
                    for (auto& dir : directions) {
                        int x = i + dir[0];
                        int y = j + dir[1];
                        if (x < 0 || x >= m || y < 0 || y >= n || grid[x][y]!= originalColor) {
                            isBorder = true;
                            break;
                        }
                    }
                    if (isBorder || i == 0 || i == m - 1 || j == 0 || j == n - 1) {
                        grid[i][j] = color;
                    }
                }
            }
        }

        return grid;
    }

    void dfs(vector<vector<int>>& grid, int row, int col, int originalColor, vector<vector<bool>>& visited, vector<vector<int>>& directions) {
        int m = grid.size();
        int n = grid[0].size();

        if (row < 0 || row >= m || col < 0 || col >= n || grid[row][col]!= originalColor || visited[row][col]) {
            return;
        }

        visited[row][col] = true;

        for (auto& dir : directions) {
            dfs(grid, row + dir[0], col + dir[1], originalColor, visited, directions);
        }
    }
