def count_set_bits(num):
    return bin(num).count('1')

def max_chocolates(T, test_cases):
    results = []
    for _ in range(T):
        N, K = test_cases[_][0]
        numbers = test_cases[_][1]
        bit_counts = [count_set_bits(num) for num in numbers]
        bit_counts.sort(reverse=True)
        results.append(sum(bit_counts[:K]))
    return results

