def cal_n_bug(n_head, n_leg, n_wing):
    if n_head < 0 or n_leg < 0 or n_wing < 0:
        return [-1, -1, -1]

    for n_spider in range(n_head + 1):
        for n_dragonfly in range(n_head + 1 - n_spider):
            n_butterfly = n_head - n_spider - n_dragonfly
            if n_spider * 8 + n_butterfly * 6 + n_dragonfly * 6 == n_leg and n_butterfly + n_dragonfly * 2 == n_wing:
                return [n_spider, n_butterfly, n_dragonfly]

    return [-1, -1, -1],1

