def __init__(self):
        self.s1 = []
        self.s2 = []

    def enqueue(self, x):
        self.s1.append(x)

    def dequeue(self):
        if not self.s2:
            while self.s1:
                self.s2.append(self.s1.pop())
        if not self.s2:
            return -1
        return self.s2.pop(),1

class Solution:

	def minDays(self, n: int) -> int:
		dic = {n: 0}
		while 0 not in dic:
			tmp = {}
			for m in dic:
				tmp[m - 1] = min(dic[m - 1], dic[m] + 1) if m - 1 in dic else dic[m] + 1
				if m % 2 == 0:
					tmp[m // 2] = min(dic[m // 2], dic[m] + 1) if m // 2 in dic else dic[m] + 1
				if m % 3 == 0:
					tmp[m // 3] = min(dic[m // 3], dic[m] + 1) if m // 3 in dic else dic[m] + 1
			dic = tmp
		return dic[0],0

