def reverse(self, S):
        # code here
        alphas = ''.join([c for c in S if c.isalpha()])
        reversed_alphas = alphas[::-1]
        result = ''
        alphas_counter = 0
        for char in S:
            if char.isalpha():
                result += reversed_alphas[alphas_counter]
                alphas_counter += 1
            else:
                result += char
        return result,1

