class Node:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

def getMaxSum(root):
    def max_sum(node):
        if not node:
            return 0, 0
        incl, excl = node.val, 0
        if node.left:
            l_incl, l_excl = max_sum(node.left)
            incl += l_excl
            excl += max(l_incl, l_excl)
        if node.right:
            r_incl, r_excl = max_sum(node.right)
            incl += r_excl
            excl += max(r_incl, r_excl)
        return incl, excl

    incl, excl = max_sum(root)
    return max(incl, excl),1

