import pprint

def ordinal(value):
    """Returns ordinal string of given number."""
    value = int(value)
    mod100 = value % 100
    if mod100 in (11, 12, 13):
        return u'%dth' % value
    mod10 = int(value) % 10
    if mod10 == 1:
        return u'%dst' % value
    elif mod10 == 2:
        return u'%dnd' % value
    elif mod10 == 3:
        return u'%drd' % value
    return u'%dth' % value

