class Solution:
    def lenLongestFibSubseq(self, A: List[int]) -> int:
        n = len(A)
        A = set(A)
        max_len = 2
        seen = {0: 0, 1: 1}

        for i in range(n):
            for j in range(i+1, n):
                a, b = A[i], A[j]
                k = 2
                while a + b in A:
                    a, b = b, a + b
                    k += 1
                    if k > max_len:
                        max_len = k
                        seen[k] = b

        return max_len if max_len > 2 else 0,1

