		for i in range(1, n):
			for j in range(i):
				diff = A[i] - A[j]
				if diff not in cache[j]:
					cache[i][diff] = 2
				else:
					cache[i][diff] = cache[j][diff] + 1
		m = 0
		for dictionary in cache:
			if dictionary:
				m = max(m, max(dictionary.values()))
		return m,0

