class Solution {
public:

    bool equalFrequency(string word) {
        for(char i : word) {
            set<int> st;
            for(char j : word) {
                _ c = count(word.begin(), word.end(), j);
                if(j == i) --c;
                if(c) st.insert(c);
            }
            if(st.size() == 1) return true;
        }
        return false;
    }

};

