class Solution {
    public List<List<Integer>> getAncestors(int n, int[][] edges) {
        // 拓扑排序
        // 从入度为0的点开始
        int[] dic = new int[n];
        List<Integer>[] g = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new ArrayList<>();
        }
        for (int i = 0; i < edges.length; i++) {
            int from = edges[i][0];
            int to = edges[i][1];
            dic[to]++;
            g[from].add(to);
        }
        List<Set<Integer>>res = new ArrayList<>();
        List<List<Integer>> ans = new ArrayList<>();
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (dic[i] == 0) {
                queue.add(i);
            }
            res.add(new HashSet<>());
            ans.add(new ArrayList<>());
        }
        while(!queue.isEmpty()) {
            int cur = queue.poll();
            for (int next : g[cur]) {
                if (--dic[next] == 0) {
                    queue.add(next);
                }
                // 不管怎么样，cur都是next的祖先
                // next需要添加cur的祖先
                res.get(next).add(cur);
                for (int now : res.get(cur)) {
                    res.get(next).add(now);
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int cur : res.get(i)) {
                ans.get(i).add(cur);
            }
            Collections.sort(ans.get(i));
        }
        return ans;

    }
