		if(g[i].size() == 1) {

			dis[i] = 0;

			Q.push_back(i);

		}

	}

	for(int i = 0; i < (int)Q.size(); i++) {

		int u = Q[i];

		for(auto v : g[u]) {

			if(dis[v] == -1) {

