			dfs(v, u);

			if(val[u].empty()) {

				val[u].swap(val[v]);

			} else {

				if(val[u].size() < val[v].size()) val[u].swap(val[v]);

				int szu = val[u].size();

				int szv = val[v].size();

				for(int k = 0; k < q; k++) {

					for(int i = 0; i < szv; i++) {

						int j = max(0, ans[k] - i - x[k] + 1);

						while(j < szu && val[u][j] + val[v][i] - 2 * dep[u] > ans[k]) {

							while(ans[k] < min(i + j + x[k], val[u][j] + val[v][i] - 2 * dep[u])) ans[k] += 1;

							j += 1;

						}

					}

				}

				for(int i = 0; i < szv; i++) {

					val[u][i] = max(val[u][i], val[v][i]);	

				}

			}

		}



		int szu = val[u].size();

		for(int k = 0; k < q; k++) {

			int j = max(0, ans[k] - dis[u] - x[k] + 1);

			while(j < szu && val[u][j] + dep[u] - 2 * dep[u] > ans[k]) {

				ans[k] += 1;

				j += 1;

			}

		}

		if(dis[u] < szu) {

			val[u][dis[u]] = max(val[u][dis[u]], dep[u]);

		} else {

			assert(dis[u] == szu);

			val[u].push_back(dep[u]);

		}

