def removeAllDuplicates(self, head):
        #code here
        prev = None
        cur = head
        dup = None
        while cur:
            if prev and cur.data == prev.data:
                if not dup:
                    dup = prev
                else:
                    if dup.data != prev.data:
                        dup = prev
                prev.next = cur.next
            else:
                if dup:
                    if dup.data == prev.data:
                        prev = dup
                    if head.data == dup.data:
                        head = prev.next
                    prev.next = cur.next
                prev = cur
            cur = cur.next
        return head,1

