function triangleType(nums) {
  if (nums.length !== 3 || nums.some(num => typeof num !== 'number' || num <= 0)) return "none";

  const sorted = [...nums].sort((a, b) => a - b);
  const sum = sorted[2] + sorted[1];

  if (sorted[0] + sorted[1] > sorted[2] && sorted[0] + sorted[2] > sorted[1] && sorted[1] + sorted[2] > sorted[0]) {
    if(sorted[0] === sorted[1] && sorted[1] === sorted[2]) {
      return "equilateral";
    } else if(sorted[0] === sorted[1] || sorted[1] === sorted[2] || sorted[0] === sorted[2]) {
      return "isosceles";
    } else {
      return "scalene";
    }
  } else {
    return "none";
  }
