class Solution {
    public int distinctIntegers(int n) {
        boolean newNum = true;
        Set<Integer> set = new HashSet<Integer>();
        set.add(n);
        while(newNum){
            newNum = false;
            List<Integer> list = new ArrayList<Integer>();
            for(Integer val: set){
                for(int i=1;i<=n;i++){
                    if(val%i==1){
                        list.add(i);
                    }
                }
            }
            for(Integer val: list){
                if(!set.contains(val)){
                    set.add(val);
                    newNum = true;
                }
            }
        }
        return set.size();
    }
