int n;

vector<vector<int>> g;



vector<int> st;

vector<int> pd;



void init(int v, int d){

	st.push_back(v);

	if (int(st.size()) - d >= 0)

		pd[v] = st[st.size() - d];

	for (int u : g[v])

		init(u, d);

	st.pop_back();

}



vector<char> used;



void dfs(int v){

	used[v] = true;

	for (int u : g[v]) if (!used[u])

		dfs(u);

}



int get(int d){

	pd.assign(n, -1);

	init(0, d);



	vector<int> ord, h(n);

	queue<int> q;

	q.push(0);

	while (!q.empty()){

		int v = q.front();

		q.pop();

		ord.push_back(v);

		for (int u : g[v]){

			q.push(u);

			h[u] = h[v] + 1;

		}

	}

	reverse(ord.begin(), ord.end());



	used.assign(n, 0);

	int res = 0;

	for (int v : ord) if (!used[v] && h[v] > d){

		++res;

		dfs(pd[v]);

	}



	return res;

}



