            case 'k':
                ++tb[4];
                break;
            default:
                return -1;
            }
            if (!is_valid(tb)) return -1;
            if (tb[0] - tb[4] >= 1)
                ma = max(ma, tb[0]-tb[4]);
        }
        for_b(i,tb.size()-1)
            if (tb[i] != tb[i+1]) return -1;
        return ma;
