class Solution {
    public int kthFactor(int n, int k) {
        int left = 0;
        int right = n;

        for (int i = 1; i <= n / i; i++) {
            if (n % i == 0) {
                if (left < k - 1) {
                    left++;
                } else if (left == k - 1) {
                    return i;
                }
                if (i!= n / i) {
                    if (right > k) {
                        right--;
                    } else if (right == k) {
                        return n / i;
                    }
                }
            }
        }
        return -1;
    }
