def postToPre(post_exp):
    stack = []
    for char in post_exp:
        if char.isalpha():
            stack.append(char)
        else:
            operand2 = stack.pop()
            operand1 = stack.pop()
            prefix_exp = char + operand1 + operand2
            stack.append(prefix_exp)
    return stack[0],1

