def solve_untreated_crimes(events):
    n = len(events)
    officers = 0
    untreated_crimes = 0

    for event in events:
        if event == -1:
            if officers > 0:
                officers -= 1
            else:
                untreated_crimes += 1
        else:
            officers += event

    return untreated_crimes

