/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
class Solution {
    public boolean checkEqualTree(TreeNode root) {
        if(root != null && root.left == null && root.right == null) return false;
        Map<TreeNode, Integer> map = new HashMap<>();
        int totalSum = populateTreeSums(root, map);
        return checkEqualTree(root, map, totalSum);
    }

    public boolean checkEqualTree(TreeNode root, Map<TreeNode, Integer> map, int totalSum) {
        if(root == null) return false;
        if(map.get(root) * 2 == totalSum) return true;
        return checkEqualTree(root.left, map, totalSum) || checkEqualTree(root.right, map, totalSum);
    }

    public int populateTreeSums(TreeNode root, Map<TreeNode, Integer> map) {
        if(root == null) return 0;
        map.put(root, populateTreeSums(root.left, map) + populateTreeSums(root.right, map) + root.val);
        return map.get(root);
    }
