def is_M_popular_items_selectable(N: int, M: int, votes: List[int]) -> str:
    votes.sort(reverse=True)
    total_votes = sum(votes)
    if M*2 >= N or M > total_votes / (1/4):
        return 'No'

    vote_threshold = total_votes / M / 4
    for vote in votes:
        if vote >= vote_threshold:
            M -= 1
        else:
            break

    return 'Yes' if M == 0 else 'No'

