def calculate_interesting_numbers(n):
    interesting_count = 0

    def s(x):
        return sum(int(digit) for digit in str(x))

    current_number = 9

    # Start with the first interesting number
    while current_number in range(1, n + 1):
        interesting_count += 1
        current_number += 1
        if s(current_number) >= s(current_number - 1):
            break

    return interesting_count

