public class Main {

    public static void main(String[] args){

        MyScanner sc = new MyScanner();

        int n = sc.nextInt();

        for(int i = 0; i<n; ++i){

            // read all input in same line

            int m = 2*sc.nextInt();

            int[] a = new int[m];

            for(int j = 0; j<m; ++j){

                a[j] = sc.nextInt();

            }

            permute(a);

        }

    }



    public static void permute(int[] a){

        // sort the array, divide into 2 equal halves,

        // insert smaller into odd, and print

        Arrays.sort(a);

        int m = a.length;

        for(int k=0; k<m/2; ++k){

            System.out.printf("%d %d ",a[k], a[k+m/2]);

        }

        System.out.print("\n");

    }



    public static class MyScanner {

        BufferedReader br;

        StringTokenizer st;



        public MyScanner() {

            br = new BufferedReader(new InputStreamReader(System.in));

        }



        String next() {

            while (st == null || !st.hasMoreElements()) {

                // If there are no tokens present, read a new line from input

                //

                // If there were tokens already present in the st object,

                // the while loop will not be executed ,and we will get the token

                // from the earlier line read from the stream.

                try {

                    st = new StringTokenizer(br.readLine());

                }

                catch (IOException e) {

                    // print exception

                    e.printStackTrace();

                }

            }

            return st.nextToken();

        }



        int nextInt() {

            return Integer.parseInt(next());

        }



        long nextLong() {

            return Long.parseLong(next());

        }



        double nextDouble() {

            return Double.parseDouble(next());

        }



        String nextLine(){

            String str = "";

            try {

                str = br.readLine();

            } catch (IOException e) {

                e.printStackTrace();

            }

            return str;

        }



    }

