#define ll long long
class Solution {
public:
    int a[2001];
    int pre[2001];
    int triangleNumber(vector<int>& nums) {
        if(nums.size()<3)
        return 0;
        memset(a,0,sizeof(a));
        memset(pre,0,sizeof(pre));
        for(int i=0;i<nums.size();i++)
        {
            a[nums[i]]++;
        }
        pre[0]=a[0]=0;
        for(int i=1;i<=2000;i++)
        {
            pre[i]=pre[i-1]+a[i];
        }
        ll sum=0;
        for(int i=0;i<=1000;i++)
        {
            if(a[i]>=3)
                sum+=(ll)a[i]*(a[i]-1)*(a[i]-2)/6;
            for(int j=i;j<=1000;j++)
            {
                if(a[i]==0 || a[j]==0)
                    continue;
                if(i==j)
                {
                    sum+=(ll)a[i]*(a[i]-1)/2*(pre[2*i-1]-a[i]);
                }
                else
                {
                    sum+=(ll)a[i]*a[j]*(pre[i+j-1]-pre[max(j,max(i,j-i))]);
                }
            }
        }
        return sum;
    }
