n, m = map(int, input().split()) 
edges = [list(map(int, input().split())) for _ in range(m)] 

def add_edges(): 
    visited = [False] * (n+1) 
    for i in range(1, n+1): 
        if not visited[i]: 
            components = [] 
            dfs(i, visited, components) 
            if len(components) > 2:
                if len(components) == 3: 
                    sum_of_elements = (components[0] + components[1] + components[2]) / 3 
                    if sum_of_elements in components[1:]:
                        needed_edges = 3 
                    else:
                        needed_edges = 2 
                else:
                    needed_edges = 1 
            else:
                needed_edges = 0 
            for j in range(len(components)): 
                for k in range(j+1, len(components)): 
                    if abs(components[j]-components[k]) not in edges: 
                        needed_edges += 1 
            total_needed_edges += min(needed_edges, 3) 
    return total_needed_edges 

def dfs(node, visited, components):
    visited[node] = True 
    components.append(node) 
    for child in adj_list[node]: 
        if not visited[child]: 
            dfs(child, visited, components) 
def build_adj_list(m): 
    adj_list = [[] for _ in range(n+1)] 
    for i in range(m): 
        adj_list[edges[i][0]].append(edges[i][1]) 
        adj_list[edges[i][1]].append(edges[i][0]) 
    return adj_list 

