def is_divisible(a, b):
    for i in range(len(b)):
        if b[i:] == a[:len(b[i:])]:
            return True
    return False

def lcm(s, t):
    if is_divisible(s, t) and is_divisible(t, s):
        return s if len(s) > len(t) else t
    else:
        return -1

