def min_distance(arr):
    n = len(arr)
    if n < 2:
        return -1

    # Sort the array in increasing order
    arr.sort()

    # Initialize variables for min and max values in the array
    min_val, max_val = arr[0], arr[-1]

    # Initialize variables to find the minimum difference
    min_diff, current_diff = 999999999, 0
    for i in range(1, n):
        current_diff = arr[i] - arr[i-1]
        if arr[i] == min_val:
            min_val = arr[i]
        if arr[i-1] == max_val:
            max_val = arr[i-1]
        if min_val != max_val and current_diff <= min_diff:
            min_diff = current_diff

    return min_diff,1

