public:
    int solve(vector<vector<int>>& graph) {
        int n = graph.size();
        vector<int> vis(n, 0);
        vector<int> dist(n, INT_MAX);
        queue<int> q;
        q.push(0);
        vis[0] = 1;
        dist[0] = 0;
        while (!q.empty()) {
            int node = q.front();
            q.pop();
            for (auto it : graph[node]) {
                if (!vis[it]) {
                    vis[it] = 1;
                    dist[it] = dist[node] + 1;
                    q.push(it);
                }
            }
        }
        return dist[n - 1];
    }
