import java.util.*;



public class solution{

    static long dp[][];

    static int n1;

    static long func(int i,int v[],int flag){

        if(i >= n1){

            return 0;

        }

        if(dp[i][flag] != -1e10){

            return dp[i][flag];

        }

        long ans = func(i+1,v,flag);

        if(flag == 0){

            ans  = Math.max(v[i] + func(i+1,v,1 - flag),ans);

        }else{

            ans  = Math.max(ans,-v[i] + func(i+1,v,1 - flag));

        }

        return dp[i][flag] = ans;

    }

    public static void main(String args[]) {

        Scanner sc = new Scanner(System.in);

        int t = sc.nextInt();

        for(int t1 = 0;t1<t;++t1){

            int n = sc.nextInt();

            int q = sc.nextInt();

            int v[] = new int[n];

            for(int i=0;i<n;++i){

                v[i] = sc.nextInt();

            }

            n1 = n;

            dp = new long[n][2];

            long h = (long)-1e10;

            for(int i=0;i<n;++i){

                for(int j=0;j<2;++j){

                    dp[i][j] = h;

                }

            }

            System.out.println(func(0,v,0));

        }

        sc.close();

    }

