# In order not to repeat calculations
cached_factorial = [0]
for i in range(1, 10 ** 6 + 1):
    cached_factorial.append(1.0 * cached_factorial[i - 1] * i % MOD)

def factorial(x):
    if x <= 10 ** 6:
        res = cached_factorial[x]
    else:
        res = 1
        for i in range(1, x + 1):
            res *= i
    return int(res) % MOD

