class Node:

	def __init__(self, data=0):
		self.data = data
		self.left = None
		self.right = None

def post_order(pre, size) -> Node:

	def insert(root, val):
		if not root:
			return Node(val)
		if val < root.data:
			root.left = insert(root.left, val)
		else:
			root.right = insert(root.right, val)
		return root
	root = None
	for i in pre:
		root = insert(root, i)
	return root,0

