using namespace std;

class Solution {
 public:
  bool primeSubOperation(vector<int>& nums) {
    constexpr int n = 1000;
    std::vector<bool> is_prime(n + 1, true);
    for (int i = 2; i * i <= n; ++i) {
      if (is_prime[i]) {
        for (int j = i * i; j <= n; j += i) {
          if (is_prime[j]) {
            is_prime[j] = false;
          }
        }
      }
    }
    vector<int> primes;
    for (int i = 2; i <= n; ++i) {
      if (is_prime[i]) {
        primes.push_back(i);
      }
    }
    int pref = 0;
    for (int x : nums) {
      if (x <= pref) {
        return false;
      }
      auto it = lower_bound(primes.begin(), primes.end(), x - pref);
      if (it == primes.begin()) {
        pref = x;
      } else {
        pref = x - *--it;
      }
    }
    return true;
  }
