class Solution {
public:
    int change(int amount, vector<int>& coins) {
        int n=coins.size();
        vector<int> dp(n+1);
        dp[0]=1;
        sort(coins.begin(), coins.end());
         for(int i=1;i<=amount;i++)
        {
            for(int j=1;j<=n;j++)
              dp[j]=0;

            for(int j=1;j<=n;j++)
            {
                if(coins[j]<=i)
                dp[i]+=dp[i-coins[j]];
            }
        }
        return dp[amount];
    }
