 */
class Solution {
public:
    vector<vector<int>> pathSum(TreeNode* root, int sum) {


        vector<vector<int>> res;
        if(!root)    return res;
        solve(root, sum,res,vector<int>());
        return res;
    }
    void solve(TreeNode* root, int sum,vector<vector<int>>& res, vector<int> ind)
    {
    	if(!root)    return;
        int temp=0;
        for(int i=0;i<ind.size();i++)
            temp += ind[i];

        res.push_back(ind);
        pushToInd(ind, root->val);
        solve(root->left, sum, res, ind);
        solve(root->right, sum, res, ind);

    }
    void pushToInd(vector<int>& ind, int val)
    {
        ind.push_back(val);

