class BIT:

	def __init__(self, n):
		self.size = n
		self.tree = [0] * (n + 1)
		self.depth = n.bit_length()

	def bitmax(self, i):
		ret = 0
		while i:
			ret = max(ret, self.tree[i])
			i ^= i & -i
		return ret

	def bitadd(self, i, x):
		while i <= self.size:
			if self.tree[i] >= x:
				break
			self.tree[i] = x
			i += i & -i
		return
