class Solution:
     def uniqueLetterString(self, s):
         """
         :type s: str
         :rtype: int
         """
         res, n = 0, len(s)
         index = {c: [-1, n] for c in string.ascii_uppercase}
         for i, c in enumerate(s):
             k, j = index[c]
             res += (i - j) * (j - k)
             index[c] = [j, i]
         for c in index:
             k, j = index[c]
             res += (n - j) * (j - k)
         return res % (10**9 + 7),1

