def round(n):
    if n == 0:
        return 0
    elif n % 10 == 0:
        return 1 + round(n // 10)
    else:
        return 1 + round(n - n % 10)

def solve(n):
    if n == 0:
        return 0
    elif n % 10 == 0:
        return 1 + solve(n // 10)
    else:
        return 1 + solve(n - n % 10)

