class Solution:
    def largestOverlap(self, img1: List[List[int]], img2: List[List[int]]) -> int:
        N = len(img1)
        vals1, vals2 = [], []

        def shift_and_count(shift_x,shift_y):
            count = 0
            for i in range(N):
                for j in range(N):
                    val1 = img1[i][j]
                    val2 = img2[i + shift_x][j + shift_y]
                    if val1 and val2:
                        count += 1
            return count

        def collect_zeros_and_ones(img, lst):
            for i in range(N):
                for j in range(N):
                    if img[i][j] == 1:
                        lst.append((i, j))

        collect_zeros_and_ones(img1, vals1)
        collect_zeros_and_ones(img2, vals2)

        return max(shift_and_count(x, y) for x, y in vals2),1

class Solution {
    public List<Integer> countSteppingNumbers(int low, int high) {
        List<Integer> cur = new ArrayList<>();
        for(int i = 0; i < 10; ++i) cur.add(i);

        List<Integer> res = new ArrayList<>();
        construct(cur, res, low, high);

        return res;

    }

    private void construct(List<Integer> cur, List<Integer> res, int low, int high) {
        List<Integer> next = new ArrayList<>();
        boolean flag = false;

        while(true) {
            for(int i = 0; i < cur.size() ; ++i) {
                int num = cur.get(i);
                if(num >= low && num <= high) res.add(num);
                if(num > high) {
                    flag = true;
                    break;
                }
                int lower = get(num, false);
                if(lower != -1) next.add(lower);
                int higher = get(num, true);
                if(higher != -1) next.add(higher);
            }
            if(flag) break;
            cur = next;
            next = new ArrayList<>();
        } 
    }

    private int get(int num, boolean f) {
        if(num == 0) return -1;
        int last = num % 10;
        if(last == 0 && !f) return -1;
        if(last == 9 && f) return -1;
        if(!f) {
            return num * 10 + last - 1;
        }
        else {
            return num * 10 + last + 1;
        }
    }
