class Solution:

	def longestOnes(self, n, a, k):
		left = right = zeros = ans = 0
		while right < n:
			if a[right] == 0:
				zeros += 1
			while zeros > k:
				if a[left] == 0:
					zeros -= 1
				left += 1
			ans = max(ans, right - left + 1)
			right += 1
		return ans,0

