class Solution {
public:
    string findLongestWord(string s, vector<string>& d) {
		sort(d.begin(), d.end());
		int len = 0;
		string ans;
		for (auto x : d) {
			int ind = -1;
			bool ok = true;
			for (auto c : x) if (ok) {
				ind = s.find(c, ind + 1);
				if (ind == string::npos)
					ok = false;
			}
			if (ok && x.size() > len) {
				len = x.size();
				ans = x;
			}
		}
		return ans;
    }
