    private static void compute(FastScanner in,BufferedWriter op) throws Exception{

        int n = in.nextInt(),m = in.nextInt();

        int[][] mat = new int[n][m];





        for(int i = 0;i<n;i++){

            String s = in.next();

            for(int j=0;j<m;j++){

                mat[i][j] = Integer.parseInt(String.valueOf(s.charAt(j)));

            }

        }



        for(int i = 0;i<n;i++){

            for(int j=0;j<m;j++){

                if(i>0 && j>0)

                {

                    if(mat[i][j]==1 && mat[i-1][j]==1 && mat[i][j-1]==1 && mat[i-1][j-1]==0)

                    {

                        op.write("NO\n");

                        return;

                    }

                }



                //up right

                if(i>0 && j<m-1)

                {

                    if(mat[i][j]==1 && mat[i-1][j]==1 && mat[i][j+1]==1 && mat[i-1][j+1]==0)

                    {

                        op.write("NO\n");

                        return;

                    }

                }



                //down right

                if(i<n-1 && j<m-1)

                {

                    if(mat[i][j]==1 && mat[i+1][j]==1 && mat[i][j+1]==1 && mat[i+1][j+1]==0)

                    {

                        op.write("NO\n");

                        return;

                    }

                }



                //down left

                if(i<n-1 && j>0)

                {

                    if(mat[i][j]==1 && mat[i+1][j]==1 && mat[i][j-1]==1 && mat[i+1][j-1]==0)

                    {

                        op.write("NO\n");

                        return;

                    }

                }

            }

        }

        op.write("YES\n");

    }



    public static void main (String[] args) throws java.lang.Exception{

        FastScanner in = new FastScanner();

        BufferedWriter op = new BufferedWriter(new OutputStreamWriter(System.out));

        int t = in.nextInt();

        while (t-- > 0){

            compute(in,op);

            op.flush();

        }

        op.close();

    }

