def kth_smallest_substring(s, k):
    n = len(s)
    substrings = set()
    for i in range(n):
        for j in range(i+1, n+1):
            substrings.add(s[i:j])
    substrings = list(substrings)
    substrings.sort()
    return substrings[k-1],1

