import java.util.LinkedList;
import java.util.Scanner;

public class MatrixMoves {

    public static LinkedList<LinkedList<Integer>> swapRows(LinkedList<LinkedList<Integer>> matrix, int row1, int row2) {
        LinkedList<LinkedList<Integer>> temp = matrix.get(row1);
        matrix.add(row1, new LinkedList<>(matrix.get(row2)));
        matrix.set(row2, temp);
        return matrix;
    }

    public static LinkedList<LinkedList<Integer>> swapColumns(LinkedList<LinkedList<Integer>> matrix, int col1, int col2) {
        for (LinkedList<Integer> row : matrix) {
            int tmp = row.get(col1);
            row.set(col1, row.get(col2));
            row.set(col2, tmp);
        }
        return matrix;
    }

    public static int makeMatrixBeautiful(LinkedList<LinkedList<Integer>> matrix) {
        for (int i = 0; i < matrix.size(); i++) {
            for (int j = 0; j < matrix.get(i).size(); j++) {
                if (matrix.get(i).get(j) == 1) {
                    return Math.min(3 - i, 3 - j);
                }
            }
        }
        return 0;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

