def is_prime(num):
    """Check if a number is prime."""
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def count_twin_primes(n, m):
    """Count pairs of twin primes (i, i+2) where both are primes."""
    twin_count = 0
    primes = [num for num in range(n, m+1) if is_prime(num)]

    for i in range(len(primes)):
        if i < len(primes) - 1:
            if is_prime(primes[i]) and is_prime(primes[i+1]) and primes[i+1] - primes[i] == 2:
                twin_count += 1

    return twin_count

