def read_nums():
	return [int(x) for x in input().split()]

def solve():
	(n, k) = read_nums()
	nums = read_nums()
	if k >= n:
		return sum(nums) + n * (2 * k - n - 1) // 2
	cum_nums = get_cum_sum(nums)
	largest_sum = 0
	for i in range(n - k + 1):
		largest_sum = max(largest_sum, cum_nums[i + k] - cum_nums[i])
	return largest_sum + k * (k - 1) // 2

def get_cum_sum(nums):
	cum_sum = 0
	cum_nums = [0]
	for num in nums:
		cum_sum += num
		cum_nums.append(cum_sum)
	return cum_nums

def main():
	(t,) = read_nums()
	for _ in range(t):
		print(solve())
