def max_prime_sum(n):
    primes = []
    res = n

    if n % 2 == 0:
        while n >= 2:
            primes.append(2)
            n -= 2
    else:
        while n >= 3:
            primes.append(2)
            n -= 2
        primes.append(3)
        n -= 3

    return len(primes), primes

