def min_time_to_collect_artifacts(m, n, forwarding_ratios, artifact_sizes, artifact_servers):
    alpha_pos = 1
    omega_pos = n - 1

    def traverse(start_pos, tgt_pos, artifact_sizes, nodes=()):
        if start_pos == tgt_pos:
            return 0
        if start_pos > tgt_pos:
            return float('inf')

        min_time = float('inf')
        for i, (s, node_pos) in enumerate(zip(artifact_sizes, artifact_servers), 1):
            if node_pos == start_pos:
                time = s * forwarding_ratios[node_pos-1] + traverse(node_pos, tgt_pos, artifact_sizes[i:], nodes + (s,))
                min_time = min(min_time, time)

        return min_time

    time_alpha = traverse(alpha_pos, omega_pos, artifact_sizes)
    time_omega = traverse(omega_pos, alpha_pos, artifact_sizes[::-1])

    return int(min(time_alpha, time_omega) + sum(forwarding_ratios) * max(artifact_sizes) // forwarding_ratios[0]),1

