def replaceWithRank(arr, N):
    # Create a dictionary to store the rank of each unique element
    rank_dict = {}

    # Sort the array while keeping track of the original indices
    sorted_arr = sorted((val, idx) for idx, val in enumerate(arr))

    # Assign ranks to each unique element
    rank = 1
    for i in range(N):
        if i > 0 and sorted_arr[i][0] != sorted_arr[i-1][0]:
            rank += 1
        rank_dict[sorted_arr[i][0]] = rank

    # Replace each element in the original array with its rank
    for i in range(N):
        arr[i] = rank_dict[arr[i]]

    return arr,1

