            if (x == Long.MIN_VALUE) {

                return print("" + x);

            }

            if (ptr + 21 >= BUF_SIZE) innerflush();

            if (x < 0) {

                print((byte) '-');

                x = -x;

            }

            int d = countDigits(x);

            for (int i = ptr + d - 1; i >= ptr; i--) {

                buf[i] = (byte) ('0' + x % 10);

                x /= 10;

            }

            ptr += d;

            return this;

        }



        public FastPrintStream print(double x, int precision) {

            if (x < 0) {

                print('-');

                x = -x;

            }

            x += Math.pow(10, -precision) / 2;

            //		if(x < 0){ x = 0; }

            print((long) x).print(".");

            x -= (long) x;

            for (int i = 0; i < precision; i++) {

                x *= 10;

                print((char) ('0' + (int) x));

                x -= (int) x;

            }

            return this;

        }



