        private void innerflush() {

            try {

                out.write(buf, 0, ptr);

                ptr = 0;

            } catch (IOException e) {

                throw new RuntimeException("innerflush");

            }

        }



        public void flush() {

            innerflush();

            try {

                out.flush();

            } catch (IOException e) {

                throw new RuntimeException("flush");

            }

        }

    }



