	if i == len(A) or j == len(B):
		return 0
	if dp[i][j] != -1:
		return dp[i][j]
	ans = 0
	if A[i] == B[j]:
		ans += f(A, B, i + 1, j + 1, dp)
	ans += f(A, B, i + 1, j, dp)
	dp[i][j] = ans
	return ans

