MAX = 102
prime = [0]*(MAX+1)

for i in range(2,MAX+1):
    if prime[i]>1: continue
    for j in range(i,MAX+1,i):
        prime[j] += 1


primelist = []
for i in range(2,MAX+1):
    if prime[i]==1:  primelist.append(i)


#print(primelist)


def factorize(num):
    output = []

    curr = num
    for p in primelist:
        if p * p > num: break

        if curr%p==0:  output.append(p)
        while curr%p==0:  curr = curr//p

    if curr < MAX and curr > 1:  output.append(curr)
    return output 


