class Solution:
    def build_btree(self, parent, x, y):
        if x and y:
            parent[x].append(y)
        elif x:
            parent[x].append(None)
        elif y:
            parent[y].append(None)

    def choose_k(self, p, v):
        if len(p) > 0:
            v = (v ^ (p[0] & p[1])) - 2 ** ((p[0] & p[3]) + (p[1] & p[3]))
        return v

    def get_leaf(self, prefix, tree, index):
        cur = tree[index]

        while cur:
            if tree[cur[1]].index(cur[0]) != index:
                tree[index][0] = cur[0]
                prefix = self.get_leaf(prefix, tree, index)
            cur = self.get_leaf(prefix, tree, cur[1])
            if cur[0]:
                cur[0] = None

    def build_bfs(self, prefix, l, r, v, p):
        if l <= 0 or r <= 0 or v < 0:
            if l <= r:
                if not p:
                    return self.build_up(rootvalue(v, [p[1]], self.choose_k(*p)))
                else:
                    self.get_leaf(prefix, tree, p)
                    if p[1] == '.':
                        return self.build_up(v, None, p)
                    else:
                        return self.build_up(v, p[1], p[3])
            v = 2 ** ((l + r) / 2)

        if l == 0 and r == 0:
            return v

        if l % 2:
            return self.build_bfs(prefix, l, r - 1, v, p)

        return self.build_bfs(prefix, l - 1, r, v, p)

    def build_up(self, value, suffix, p):
        cur = [p[0], p[1], p[0]]
        tree = [(0, [0])]

        cur[0] = value
        cur[1] = p[3] if p[3] != '.' else None
        tree[0][0] = cur[1] if not p[1] == '.' else cur[0]
        cur[2] = None

        count = 1
        while cur[1]:
            cur[0] = tree[(cur[1] ^ cur[2])[0][1]][0]
            cur[2] = tree[(cur[1] ^ cur[2])[0][1]][1]
            count += 1

        count = self.build_up(cur[0], cur[2], p)
        if cur[2]:
            cur[1] = p[1] + [[cur[2][0]], cur[2][1], p[3]]

        tree.append(cur)
        return count

    @staticmethod
    def output(s, prefixes=('0', '1')):
        return ''.join([prefixes[x] + cur for (x, cur) in enumerate(s[::-1], start=1)])


struct SuffixTrie:
    id, idx, s, start, end: int

    def pressKey(self, key):
        self.start, self.end = key.start, key.end
        c, id = key.arg
        data = SuffixTrie(id, 0, 0, 0, 0)

        def newNode(id, size, val):
            val = int(val)
            if val == 0:
                self.end = 0
                return
            val = val << 1
            if data.end - data.start < size:
                data.start = data.end = size
                return
            data.end -= size + 1
            for _ in range(size):
                val += int(data.id | c)
                self.start = val
                if val <= data.end:
                    return
                data.idx += 1

        newNode(int(key.idx), len(key.s), key.s)
        data.s = key.s[::-1]

        while self.end:
            newNode(int(key.arg[1]), len(key.s[1:]) + len(key.s[:1]), key.s)
            if key.idx == self.end:
                return data.s

            self.end -= 1


