class Solution {
    public int maxValue(int[][] A, int K) {
        int res=0;
        int n=A.length;
        TreeMap<Integer,Integer>treemap=new TreeMap<>();
        Arrays.sort(A,(a,b)->{
            return a[1]-b[1];
        });


        Seg segs[]=new Seg[K+1];
        for(int i=0;i<segs.length;i++){
            segs[i]=new Seg(0,n);
        }

        int dp[][]=new int[A.length][K+1];

        for(int i=0;i<A.length;i++){
            int s=A[i][0];
            int e=A[i][1];
            int v=A[i][2];
            res=Math.max(res,v);
            segs[1].update(i,v);
            //System.out.println(treemap);
            for(int k=1;k<=Math.min(i+1,K);k++){
                Integer index=treemap.floorKey(s-1);
                if(index==null){
                    break;

                }
                else{
                    int mx=segs[k-1].query(0,treemap.get(index));
                    if(mx!=Integer.MIN_VALUE){
                        segs[k].update(i,v+mx);
                        res=Math.max(res,v+mx);
                        //System.out.println("b  "+index+"    "+i+"  "+k+"   "+(v+mx));
                    }
                }
            }
            treemap.put(e,i);
        }
        return res;
    }

    //public int dfs(int A[][],int end)



    class Seg{
        int l,r;
        int max=Integer.MIN_VALUE;
        Seg left=null,right=null;
        public Seg(int l,int r){
            this.l=l;
            this.r=r;
            if(l!=r){
                int mid=l+(r-l)/2;
                if(l<=mid)left=new Seg(l,mid);
                if(r>=mid+1)right=new Seg(mid+1,r);
                if(left!=null)max=Math.max(left.max,max);
                if(right!=null)max=Math.max(right.max,max);
            }else{
                max=Integer.MIN_VALUE;
            }
        }
        public int query(int s,int e){
            if(l==s&&r==e){
                return max;
            }
            int mid=l+(r-l)/2; //left :  to mid-1,
            if(e<=mid){
                return left.query(s,e);
            }
            else if(s>=mid+1){
                return right.query(s,e);
            }else{
                return Math.max(left.query(s,mid),right.query(mid+1,e));
            }
        }

        public void update(int index,int v){
            if(l==r){
                max=v;
                return;
            }
            int mid=l+(r-l)/2;
            if(index<=mid){
                left.update(index,v);
            }else{
                right.update(index,v);
            }
            this.max=Math.max(left.max,right.max);
        }
    }
