def maxHappiness(happiness, k):
    prefix_sums = [0] * (len(happiness) + 1)
    for i in range(len(happiness)):
        prefix_sums[i+1] = prefix_sums[i] + happiness[i]

    children = [(happiness[i], i) for i in range(len(happiness))]
    children.sort(reverse=True)

    dp = [0] * (k + 1)
    for i in range(1, len(children) + 1):
        for j in range(k, 0, -1):
            dp[j] = max(dp[j], dp[j-1] + children[i-1][0] - (prefix_sums[children[i-1][1]] - prefix_sums[children[i-1][1] - 1]) if children[i-1][1] > 0 else children[i-1][0])

    return dp[k],1

