def is_letter_x(n, paper):
    # Check the first character on the first diagonal
    diag_char = paper[0][0]
    # Check the first character on the second diagonal
    anti_diag_char = paper[0][n-1]
    # Ensure the two diagonal characters are different
    if diag_char == anti_diag_char:
        return "NO"

    # Check all the characters on the diagonals and off-diagonals
    for i in range(n):
        for j in range(n):
            if i == j or i + j == n - 1:
                # Check diagonal characters
                if paper[i][j] != diag_char:
                    return "NO"
            else:
                # Check off-diagonal characters
                if paper[i][j] != anti_diag_char:
                    return "NO"

    return "YES"

