#include <iostream>
#include <queue>

using namespace std;

typedef long long ll;

priority_queue<pair<ll, ll>> pq;

void solve(ll n) {
    pq.push({n, 1});
    vector<pair<ll, ll>> res;

    while(pq.size() > 1) {
        auto it1 = pq.top();
        pq.pop();
        auto it2 = pq.top();
        pq.pop();

        res.push_back({it1.second, it2.second});

        if(it1.first + it2.first > 2) {
            if(it1.first < it2.first) {
                pq.push({it1.first, it1.second});
                pq.push({it2.first - it1.first, it2.second});
            } else {
                pq.push({it2.first, it2.second});
                pq.push({it1.first - it2.first, it1.second});
            }
        }
    }

    cout << (pq.top().first + 1) / 2 << '\n';
    for(auto it: res) {
        cout << it.first << ' ' << it.second << '\n';
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    int t;
    cin >> t;
    while(t--) {
        ll n;
        cin >> n;
        solve(n);
    }

    return 0;
