def main():
	for _ in range(int(input())):
		(l, r, a) = map(int, input().split())
		if a == 1 or a > r:
			f = r
		elif r % a == 0:
			x = max(l, r - 1)
			f = x // a + x % a
		elif l < a < r:
			f = max(r // a + r % a, max(r // a - 1, l // a) + a - 1)
		elif a < l < r:
			(la, ra) = (l // a, r // a)
			f = max(ra + r % a, ra + a - 2 if la < ra else 0)
		else:
			f = max(map(lambda x: x // a + x % a, range(max(l, r - 1 - r % a), r + 1)))
		output.append(f)
	print(*output, sep='\n')
