class Solution:

	def smallestSumSubarray(self, A, N):
		min_sum = A[0]
		current_sum = A[0]
		for i in range(1, N):
			current_sum = min(A[i], current_sum + A[i])
			min_sum = min(min_sum, current_sum)
		return min_sum,0

