def solve(s, t):
    from collections import Counter

    # Check if we can solve the problem with only suffix automaton
    def can_use_automaton(s, t):
        counter_s = Counter(s)
        counter_t = Counter(t)
        for char in counter_t:
            if counter_t[char] > counter_s.get(char, 0):
                return False
        return True

    # Check if we can solve the problem with only suffix array
    def can_use_array(s, t):
        return Counter(s) == Counter(t)

    if can_use_array(s, t):
        if can_use_automaton(s, t):
            return "both"
        else:
            return "array"
    elif can_use_automaton(s, t):
        return "automaton"
    else:
        return "need tree"

