def polycarp(a, b, c, d):
    total_sleep = 0
    current_time = b
    while total_sleep < a:
        if current_time > a:
            return -1
        total_sleep += min(current_time, a - total_sleep)
        current_time += c
    return current_time,1

def alg(n, k):
	if 0 <= k <= n:
		ntok = 1
		ktok = 1
		for t in range(1, min(k, n - k) + 1):
			ntok *= n
			ktok *= t
			n -= 1
		return ntok // ktok
	else:
		return 0
