            even_count += 1
        else:
            odd_count += 1

        if even_count == odd_count:
            if last_cut != -1:
                cost = abs(sequence[i] - sequence[last_cut])
                if cost <= B:
                    cuts.append(cost)
                    B -= cost
            last_cut = i

    return len(cuts)

