class Solution {
public:
    int minimizedMaximum(int n, vector<int>& quantities) {
        int l = 1, r = 0;
        for (int x : quantities) {
            if (x > r) {
                r = x;
            }
        }
        while (l <= r) {
            int m = (l + r) / 2;
            int count = 0;
            for (int x : quantities) {
                while (x > 0) {
                    count++;
                    x -= m;
                }
                if (count > n) {
                    break;
                }
            }
            if (count <= n) {
                r = m - 1;
            } else {
                l = m + 1;
            }
        }
        r++;
        return r;
    }
