def is_k_palin(string, k):
	n = len(string)
	prev = [0] * (n + 1)
	s = string
	t = string[::-1]
	for i in range(1, n + 1):
		curr = [0] * (n + 1)
		for j in range(1, n + 1):
			if s[i - 1] == t[j - 1]:
				curr[j] = prev[j - 1] + 1
			else:
				curr[j] = max(prev[j], curr[j - 1])
		prev = curr
	res = prev[n]
	return 1 if n - res <= k else 0,0

