class Array:

    def __init__(self, iterable = None, null_val= None, null_index = -1, duplicate_elim = None):
        self.null_val = null_val
        self.null_index = null_index
        self.duplicate_elim = duplicate_elim
        if iterable == None:
            self.arraylist = []
            self.length = 0
        else:
            if self.duplicate_elim == None: pass
            elif self.duplicate_elim == False: pass
            elif self.duplicate_elim == True: iterable = [x for x in set(iterable)]
            elif self.duplicate_elim == "left": iterable = [x for n, x in enumerate(iterable) if x not in iterable[:n]]
            elif self.duplicate_elim == "right": iterable = [x for n, x in enumerate(iterable) if x not in iterable[n + 1:]]
            self.arraylist = self.circularize(iterable, self.null_index, self.null_val, True)
            self.length  = len(self.arraylist)

