        new = []
        s1 = self.circularize(self.arraylist, self.null_index)
        s2 = self.circularize(other.arraylist, other.null_index)
        for i in s1:
            if i == self.null_val: break
            new.append(i)
        for i in s2:
            if i == other.null_val: break
            new.append(i)
        return Array(new, self.null_val, self.null_index)

    def __eq__(self, other):
        s1 = self.circularize(self.arraylist, self.null_index)
        s2 = self.circularize(other.arraylist, other.null_index)
        for i in range(self.length):
            if s1[i] != s2[i]: return False
        return True

    def __getitem__(self, key):
        return self.arraylist[key]

