/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
class Solution {
    public TreeNode subtreeWithAllDeepest(TreeNode root) {
        return helper(root).node;
    }
    private resNode helper(TreeNode root){
        if(root == null) return new resNode(0, null);
        if(root.left == null && root.right == null) return new resNode(1, root);
        resNode left = helper(root.left);
        resNode right = helper(root.right);
        if(right.depth > left.depth) return new resNode(right.depth+1, right.node); // right node
        if(left.depth > right.depth) return new resNode(left.depth+1, left.node); // left node
        return new resNode(left.depth+1, root); //root
    }
}
class resNode{
    int depth;
    TreeNode node;
    public resNode(int depth, TreeNode node){
        this.depth = depth;
        this.node = node;
    }
