        int[] ria(int n) {

            int[] a = new int[n];

            for (int i = 0; i < n; i++) a[i] = Integer.parseInt(next());

            return a;

        }



        long nextLong() {

            return Long.parseLong(next());

        }



        long[] rla(int n) {

            long[] a = new long[n];

            for (int i = 0; i < n; i++) a[i] = Long.parseLong(next());

            return a;

        }



        double nextDouble() {

            return Double.parseDouble(next());

        }



        String nextLine() {

            String str = "";

            try {

                str = br.readLine();

            } catch (IOException e) {

                e.printStackTrace();

            }

            return str;

        }

    }

