However, this solution is not efficient due to the overlapping subproblems in the recursive call. We can use dynamic programming to optimize the solution.

Here's the optimized solution:

'''python
def teleporter(arr, coins):
    n = len(arr)
    dp = [0] * (coins + 1)
    dp[0] = 1  # base case, we can use 0 teleporters with 0 coins
    for i in range(n):
        for j in range(arr[i], coins + 1):
            dp[j] = max(dp[j], dp[j - arr[i]] + 1)
    return dp[coins]

def main():
    t = int(input())
    for _ in range(t):
        n, coins = map(int, input().split())
        arr = list(map(int, input().split()))
        print(teleporter(arr, coins))

if __name__ == '__main__':
    main()
