from math import gcd
from typing import List

def solve(arr: List[int]) -> int:
    n = len(arr)
    dp = [1] * n
    for i in range(1, n):
        if gcd(arr[i], arr[i - 1]) == 1:
            dp[i] = dp[i - 1] + 1
    max_val = max(dp)
    if max_val == 1:
        return -1
    else:
        return max_val

def main():
    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        print(solve(arr))

