function miniMaxSum(arr){
    let totalSum = arr.reduce((acc, val) => acc + val, 0);
    let minSum = totalSum - Math.max(...arr);
    let maxSum = totalSum - Math.min(...arr);
    return [minSum, maxSum];
}

