// Implementation
function quickSort(array) {
    if (array.length <= 1) {
        return array;
    }

    const index = Math.floor(array.length / 2);
    const higher = [];
    const lower = [];

    for (let i = 0; i < array.length; i++) {
        if (i !== index) {
            if (array[i] < array[index]) {
                lower.push(array[i]);
            } else {
                higher.push(array[i]);
            }
        }
    }

    return [...quickSort(lower), array[index], ...quickSort(higher)];
}

