function proceed(arrayToProcess){
    let output = arrayToProcess.map(l=>l.split(" ").map(m=>parseInt(m)));
    let result = [];
    let beginIndex = -1;
    for (let xInRange = 0; xInRange < output.length; xInRange++) {
        for (let yInRange = 0; yInRange < output[xInRange].length; yInRange++) {
            beginIndex++;
            let rangeX = Math.min(output.length - xInRange - 1, yInRange);
            let rangeY = Math.min(output[xInRange].length - yInRange - 1, xInRange);
            for (let xIndex = xInRange - rangeX; xIndex <= xInRange + rangeX; xIndex++) {
                for (let yIndex = yInRange - rangeY; yIndex <= yInRange + rangeY; yIndex++) {
                    result[beginIndex] = output[xIndex][yIndex];
                }
            }
        }
    }
    return result;
}

