from queue import Queue

# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
class Solution:
    def deepestLeavesSum(self, root: TreeNode) -> int:
        q = Queue()
        q.put(root)
        while not q.empty():
            sumi=0
            for i in range(q.qsize()):
                node=q.get()
                sumi+=node.val
                if node.left!=None:
                    q.put(node.left)
                if node.right!=None:
                    q.put(node.right)
        return sumi<|endoftext|>class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
class Solution:
    def balanced(self, root):
        if(root is None):
            return 0

        left=self.balanced(root.left)
        right=self.balanced(root.right)

        height=abs(left-right)

        if left==-1 and right==-1:
            return False

        if left is not -1 and right is not -1:
            if(height<=1):
                return 1+max(left,right)
            else:
                return -1

    def isBalanced(self, root: TreeNode) -> bool:
        return self.balanced(root)!=-1

