    def strangePrinter(self, s: str) -> int:
        n = len(s)
        dp = [[1 for _ in range(n)] for __ in range(n)]
        for i in range(n):
            dp[i][i] = 1

        def cal(l, r):
            if dp[l][r] != 1:
                return dp[l][r]
            if l > r:
                dp[l][r] = 0
                return 0
            ans = cal(l + 1, r) + 1
            for i in range(l + 1, r + 1):
                if (s[i] == s[l]):
                    ans = min(ans, cal(l, i - 1) + cal(i + 1, r))
            dp[l][r] = ans
            return ans

        return cal(0, len(s) - 1)

