#define int long long
const int mod = 1e9 + 7;

void primeFactors(int n, map<int, int> &M) {
    if (n % 2 == 0) {
        M[2]++;
        while (n % 2 == 0)
            n /= 2;
    }
    for (int i = 3; i <= sqrt(n); i += 2) {
        if (n % i == 0) {
            M[i]++;
            while (n % i == 0)
                n /= i;
        }
    }
    if (n > 2)
        M[n]++;
}

void solve() {
    int p, q;
    cin >> p >> q;
    map<int, int> M1, M2;
    primeFactors(p, M1);
    primeFactors(q, M2);
    if (p % q!= 0) {
        cout << p << endl;
        return;
    }
    int ans = 1;
    for (auto &it : M1) {
        int pf = it.first;
        int pw = it.second;
        if (M2.find(pf) == M2.end() || M2[pf] < pw) {
            int tmp = 1;
            for (int i = 0; i < pw; i++)
                tmp *= pf;
            ans = max(ans, tmp / power(pf, M2[pf]));
        }
    }
    cout << ans << endl;
}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    int t;
    cin >> t;
    while (t--) {
        solve();
    }
    return 0;
