def move(x, y, direction):
    if direction == '>':
        nx, ny = x + 1, y
    elif direction == '<':
        nx, ny = x - 1, y
    elif direction == '^':
        nx, ny = x, y - 1
    else:
        nx, ny = x, y + 1

    return nx, ny

