class Solution:

	def NoOfChicks(self, N):
		l = [0 for i in range(N + 1)]
		l[1] = 1
		sum = l[1]
		for i in range(2, N + 1):
			if i > 6:
				sum -= l[i - 6]
			l[i] = sum * 2
			sum += l[i]
		return sum,0

